//! The Sanskrit model, generated by flexion-train from configs/src/sanskrit.rs: one
//! module per part of speech (and per helper model), each a
//! [`flexion::PosModel`]. Don't edit by hand.

use flexion::{Model, PosModel, Spelling, SpellingStrings};

mod noun;
mod adjective;
mod verb;
mod pronoun;
mod verb_from_cell_96;
mod verb_from_cell_150;

static STRINGS: SpellingStrings<'static> = SpellingStrings {
    stress_marks: "",
    stress_table: "",
    vowels: "अआइईउऊऋॠऌॡएऐओऔ",
    implicit: "",
    fold_from: "",
    fold_to: "",
    strip_marks: "\u{951}\u{952}",
    unmark_from: "",
    unmark_to: "",
    syllabic: "कखगघङचछजझञटठडढणतथदधनपफबभमयरलळवशषसह",
    mute: "\u{94d}",
    diphthongs: "",
    hiatus: "",
};

/// The model, in the config's order of parts of speech (helper models
/// after).
pub(crate) fn build() -> Model<'static> {
    Model::new(
        Spelling::new(false, false, STRINGS),
        vec![
            &noun::Noun as &dyn PosModel,
            &adjective::Adjective as &dyn PosModel,
            &verb::Verb as &dyn PosModel,
            &pronoun::Pronoun as &dyn PosModel,
            &verb_from_cell_96::VerbFromCell96 as &dyn PosModel,
            &verb_from_cell_150::VerbFromCell150 as &dyn PosModel,
        ],
    )
}

/// Whether every part of speech's sound laws compile.
pub(crate) fn sound_laws_compile() -> bool {
    noun::sound_laws_compile() && adjective::sound_laws_compile() && verb::sound_laws_compile()
}
